model:
rachana: 1
sutra: fund-holder
version: 1
description: 
match: { kind: fund-holder, priority: 10 }
title: { pill: "Funds · Held by funds", id: "$.TICKER", with: "$.NAME" }
strip:
  - { label: "Company", bind: "link($.COMPANY, 'us-company', $.NAME)" }
  - { label: "Funds", bind: "$.FUNDS", fmt: "amount0", emphasis: true }
  - { label: "of which ETFs", bind: "$.ETFS", fmt: "amount0" }
  - { label: "Value held", bind: "$.TOTAL_VALUE", fmt: "compact" }
  - { label: "Share of its shares", bind: "$.PCT_OF_SHARES", fmt: "weight2" }
  - { label: "Average weight", bind: "$.AVG_WEIGHT", fmt: "weight3" }
  - { label: "Largest weight", bind: "$.MAX_WEIGHT", fmt: "weight2" }
panels:
  - id: holders
    kind: table
    title: "Funds holding ${$.NAME}, by value (a fund opens its page)"
    key: "F2"
    code: "HLD"
    rows: "$.HOLDERS"
    empty: "No fund of the pack holds this company"
    columns:
      - { label: "Fund", bind: "link(@.FUND, 'fund', @.FUND_NAME)" }
      - { label: "Ticker", bind: "@.FUND" }
      - { label: "Type", bind: "@.TYPE" }
      - { label: "Weight in the fund", bind: "@.PCT", fmt: "weight3" }
      - { label: "Value", bind: "@.VALUE", fmt: "compact", total: true }
      - { label: "Shares", bind: "@.SHARES", fmt: "compact", total: true }
      - { label: "Report date", bind: "@.REPORT_DATE", fmt: "date" }
  - id: by-weight
    kind: hbar
    title: "The ten largest weights in a fund (%)"
    key: "F3"
    area: right
    phone: { tier: "glance", from: "fragment", rows: 5 }
    rows: "$.TOP_WEIGHTS"
    label: "FUND"
    value: "PCT"
    fmt: "weight2"
  - id: note
    kind: markdown
    title: "About this page"
    area: right
    phone: { tier: "more", from: "fragment" }
    text: "Public data (U.S. public domain): every holding of the company in the pack's 200 funds, as each filed it on Form N-PORT for its own report date, shares and value as filed. The share of the company's shares compares the shares held with those outstanding on its latest 10-K cover (us-equities); it is left empty where the filed count cannot be compared. Source: drishti.py feed run funds."
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
keys: { F5: "link($.COMPANY, 'us-company', $.NAME)", F9: "raw" }
